#include <iostream>
#include <vector>
#include <string.h>

void replaceCharStrings(std::vector<std::string>& arr, std::string newValue) {
    for(size_t i = 0; i < arr.size(); ++i) {
        if(arr[i].length() == 1) { // If the string has only one character
            arr[i] = newValue; // Replace it 
        }
    }
}

int main() {
    std::vector<std::string> arr = {"", "a", "b", ""};

    replaceCharStrings(arr, "nonEmptyValue");

    for(size_t i = 0; i < arr.size(); ++i) {
        std::cout << arr[i] << " ";
    }

    return 0;
}
