```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public class Program
{
    private static readonly ConcurrentBag<int> SharedList = new ConcurrentBag<int>();

    static void Main(string[] args)
    {
        SharedList.Add(1);
        SharedList.Add(4);
        SharedList.Add(7);
        SharedList.Add(9);

        var tasks = new List<Task>
        {
            Task.Run(() => AddNumber(10)),
            Task.Run(() => CheckNumber(7)),
        };

        try
        {
            Task.WaitAll(tasks.ToArray());
        }
        catch (AggregateException ae)
        {
            foreach (var e in ae.InnerExceptions)
            {
                Console.WriteLine(e.Message);
            }
        }

        Console.ReadKey();
    }

    public static void AddNumber(int num)
    {
        SharedList.Add(num);
        Console.WriteLine($"Added {num}");
    }

    public static void CheckNumber(int num)
    {
        bool exists = SharedList.Contains(num);
        Console.WriteLine(exists ? $"Number {num} exists in the array." : $"Number {num} does not exist in the array.");
    }
}
```
In the above sample code: 

- We are using a `ConcurrentBag<T>` which represents a thread-safe, unordered collection of objects. It is used as our shared list (or array) which can be safely modified while being accessed.
- The `Main()` function sets up our tasks to be run concurrently:
  * `Task.Run(() => AddNumber(10))`: This will add the number 10 to the array concurrently.
  * `Task.Run(() => CheckNumber(7))`: This will check for the existence of the number 7 in the array concurrently.
- We handle any exceptions thrown in our tasks with an `AggregateException`, displaying the message for each nested exception.

You can add or check as many numbers as you like by adding more tasks to the tasks list. Be aware that due to the non-deterministic nature of multithreading, the order in which the tasks will be executed cannot be guaranteed. So, you may see unexpected results if you check for a number before it is added.

