const uuidv5 = require('uuid').v5;

/**
 * Generate a UUIDv5 based on the provided namespace and name.
 * @param {string} namespace - Namespace identifier.
 * @param {string} name - The name string.
 * @return {string} The generated UUIDv5 string.
 */
function generateUUIDv5(namespace, name) {
    // Check for valid inputs
    if (typeof namespace !== 'string' || typeof name !== 'string') {
        throw new Error('Invalid inputs. Both namespace and name must be strings.')
    }

    // UUID v5 uses deterministic algorithms (i.e., same input will always produce the same output); they are SHA-1 hash based.
    try {
        return uuidv5(name, namespace);
    } catch (error) {
        // Handle any errors from the uuidv5 library
        throw error;
    }
}

