function isPrime(num) {
    if (typeof num !== 'number' || !Number.isInteger(num)) {
        throw new Error('The input must be an integer.');
    }

    if (num < 2) return false;
    for (let i = 2, sqrt = Math.sqrt(num); i <= sqrt; i++) {
