function displayPrimes(upTo) {
    if (typeof upTo !== 'number' || !Number.isInteger(upTo)) {
        throw new Error('The input must be an integer.');
    }

    let primes = [];
    for (let i = 2; i <= upTo; i++) {
        if (isPrime(i)) primes.push(i);
    }

    return primes;
}

