for i in range(2, N):

    fac.append( ( fac[-1] * i ) % MOD )

    inv.append( ( -inv[MOD % i] * (MOD//i) ) % MOD )

    facinv.append( (facinv[-1] * inv[-1]) % MOD )



# 部分木のDP値を求めていく

# u : 求める頂点

