def dfs(u, p = -1):



    global DP, CN, E



    # tmp_ans = 1

    # tmp_cn = 0  # （自分を含む）部分木のノード数



    # u から出ている頂点 v

    for v in E[u]:

        if not v == p:  # 親への辺以外について

            DP[v], CN[v] = dfs(v, u)

            CN[u] += CN[v]

            DP[u] *= DP[v] * cmb(CN[u], CN[v])

    CN[u] += 1



    return DP[u], CN[u]



# 各頂点の真のDP値を求めていく



def bfs(u, p=-1):



    global DP, E



    for v in E[u]:  # 各vに対して「真のDP値」を求めていく

        if v == p:

            continue



        # DP[u] と DP[v] から DP[v <- u] を求める

        cnv = CN[v]

        tmp_cn = N - cnv  # v から見たときの u の部分木の要素数

        DP[v] = DP[u] * cnv / tmp_cn 



        bfs(v, u)



    return



