def f(x, X, VX):

    visit_node = [set(), set()]

    visit_link = set()



    q = queue.Queue()

    q.put((0, x))

    while not q.empty():

        p, s = q.get()

        if s in visit_node[p]:

            continue



        visit_node[p].add(s)

        VX[p][s] = True

        for t in X[p][s]:

            l = (s, t) if p == 0 else (t, s)

            if l in visit_link:

                continue

            visit_link.add(l)



            if t in visit_node[1 - p]:

                continue

            q.put((1 - p, t))



    return len(visit_node[0]) * len(visit_node[1]) - len(visit_link)





