Here is a Python solution using an object-oriented approach:

```python
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class BinaryTree:
    def __init__(self, root):
        self.root = TreeNode(root)

    def isBST(self, node, min_val=float('-inf'), max_val=float('inf')):
        if node is None:
            return True

        if not min_val <= node.val <= max_val:
            return False

        return (self.isBST(node.left, min_val, node.val - 1) and
                self.isBST(node.right, node.val+1, max_val))

    def getHeight(self, root):
        if root is None:
            return 0

        return max(self.getHeight(root.left), self.getHeight(root.right)) + 1

    def getBalance(self, root):
        if root is None:
            return 0

        return self.getHeight(root.left) - self.getHeight(root.right)

    def insertNode(self, root, key):
        if not root:
            return TreeNode(key)
        if root.val > key:
            root.left = self.insertNode(root.left, key)
        else:
            root.right = self.insertNode(root.right, key)

        root.height = 1 + max(self.getHeight(root.left),
                              self.getHeight(root.right))

        balance = self.getBalance(root)

        if balance > 1 and key < root.left.val:
            return self.rightRotate(root)

        if balance < -1 and key > root.right.val:
            return self.leftRotate(root)

        if balance > 1 and key > root.left.val:
            root.left = self.leftRotate(root.left)
            return self.rightRotate(root)

        if balance < -1 and key < root.right.val:
            root.right = self.rightRotate(root.right)
            return self.leftRotate(root)

        return root

    def rightRotate(self, z):
        y = z.left
        T3 = y.right
        y.right = z
        z.left = T3
        z.height = 1 + max(self.getHeight(z.left),
                            self.getHeight(z.right))
        y.height = 1 + max(self.getHeight(y.left),
                            self.getHeight(y.right))

        return y

    def leftRotate(self, z):
        y = z.right
        T3 = y.left
        y.left = z
        z.right = T3
        z.height = 1 + max(self.getHeight(z.left),
                           self.getHeight(z.right))
        y.height = 1 + max(self.getHeight(y.left),
                           self.getHeight(y.right))

        return y

    def balanceTree(self, root):
        if root is None or (self.isBST(root) and self.getBalance(root) in (-1, 0, 1)):
            return root

        if self.getBalance(root) > 1:
            if self.getBalance(root.left) >= 0:
                return self.rightRotate(root)
            else:
                root.left = self.leftRotate(root.left)
                return self.rightRotate(root)

        else:
            if self.getBalance(root.right) <= 0:
                return self.leftRotate(root)
            else:
                root.right = self.rightRotate(root.right)
                return self.leftRotate(root)
```

This BinaryTree class can create nodes, insert nodes in a way that tree always remains balanced. It uses right and left rotations to make sure that tree always stays balanced. It also checks if the binary tree is a BST and if it's balanced or not. If it's not balanced, there is a function to balance it. The balance of the tree is found by taking the difference of the height of the left subtree and the right subtree.

