    }

    public static void reverseSentences(String text) {
        String[] sentences = text.split("。");
        ArrayList<String> sentencesList = new ArrayList<String>(Arrays.asList(sentences));
        Collections.reverse(sentencesList);
        String reversedText = String.join("。", sentencesList);
        System.out.println(reversedText);
    }
}
