Here is the corrected code.

```javascript
function leastFrequentCharacter(text) {
  if (typeof text !== 'string') {
    return 'Error: Input should be a string.';
  }
  if (text.length === 0) {
    return 'Error: Empty string is not allowed.';
  }

  let charCounts = {};
  for (let i = 0; i < text.length; i++) {
    if (charCounts.hasOwnProperty(text[i])) {
      charCounts[text[i]]++;
    } else {
      charCounts[text[i]] = 1;
    }
  }

  let minCount = Infinity;
  let minChars = {};
  for (let char in charCounts) {
    if (charCounts[char] < minCount) {
      minCount = charCounts[char];
      minChars = { [char]: minCount };
    } else if (charCounts[char] === minCount) {
      minChars[char] = minCount;
    }
  }

  return minChars;
}

