bool isPrime(int num) {
    if(num < 2) 
        return false;
    for(int i=2; i*i<=num; i++) {
        if(num%i == 0)
            return false;
    }
    return true;
}

int compute(vector<int> lst){
    int maxnum = -1;
    for(int i=0; i<lst.size(); i++) {
        if(isPrime(lst[i]) && lst[i]>maxnum)
            maxnum = lst[i]; 
    }
    if(maxnum == -1)
        return -1;
    int sum = 0;
    while(maxnum)
    {
        sum += maxnum%10;
        maxnum /= 10;
    }
    return sum;
}
