def slv(S, T):

    if len(set(c for c in T) - set(c for c in S)) > 0:

        return -1



    from collections import defaultdict

    si = defaultdict(list)

    for i, c in enumerate(S):

        si[c].append(i)



    ans = 0

    ci = 0

    from bisect import bisect_left

    for i, c in enumerate(T):

        j = bisect_left(si[c], ci)

        if j == len(si[c]):

            j = 0

            ans += 1

        ci = si[c][j] + 1

    return (ans)*len(S) + ci











