def SieveOfEratosthenes(n, limit):
    prime = [True for i in range(n + 1)]
    p = 2
    while p * p <= n:
        if prime[p] == True:
            for i in range(p * p, n+1, p):
                prime[i] = False
        p += 1
    sum = 0
    for p in range(limit, n):
        if prime[p]:
            sum += p
    return sum

