def get_prime_factors(x):

    out = []

    if x < 1:

        return out

    while not x%2:

        out.append(2)

        x //= 2

    i = 3

    while i*i <= x:

        if not x%i:

            out.append(i)

            x //= i

        else:

            i += 2

    if x != 1:

