import java.util.Scanner;

public class MirrorArray {

    private static void printMirroredStringArray(String[] array) {
        if(array != null) {
            for (int i = 0; i < array.length; i++) {
                System.out.println(array[i] + "   " + array[i]);
            }
        } else {
            System.out.println("Invalid Input");
        }
    }

    private static String[] textualSequenceToArray(String sequence) {
        if(sequence != null && !sequence.equals("") && sequence.matches("[a-zA-Z ]*") && sequence.length() <= 50) {
            String[] arr = new String[sequence.length()];
            for (int i = 0; i < sequence.length(); i++) {
                arr[i] = Character.toString(sequence.charAt(i));
            }
            return arr;
        } else {
            return null;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter a textual sequence:");
        String sequence = scanner.nextLine();
        printMirroredStringArray(textualSequenceToArray(sequence));
    }
}
