class MyList(list):

    def __init__(self, x=[]):

        list.__init__(self, x)



    def __iadd__(self, A):

        return MyList([a + b for a, b in zip(self, A)])



    def __isub__(self, A):

        return MyList([a - b for a, b in zip(self, A)])



    def __gt__(self, A):

