```java
public class Main {
    public static void main(String[] args) {
        int lowerLimit = 10;
        int upperLimit = 20;
        int specifiedNumber = 15;

        System.out.println("Placement of specified number: " + isNumberInInterval(lowerLimit, upperLimit, specifiedNumber));
