     * Checks if a specified number is in a given interval.
     *
     * @param lowerLimit The lower limit of the interval.
     * @param upperLimit The upper limit of the interval.
     * @param specifiedNumber The number to check.
     * @return true if the number is in the interval, else false.
     */
    public static boolean isNumberInInterval(int lowerLimit, int upperLimit, int specifiedNumber) {
        return specifiedNumber >= lowerLimit && specifiedNumber <= upperLimit;
    }
}
