            raise ValueError("value_in_usd should be a positive number!")
        self._value_in_usd = v

    def convert_to(self, another_currency):
        # Avoid direct accessing of other object's property
        return self._value_in_usd / another_currency.value_in_usd 

    def compare_to(self, another_currency):
        if self._value_in_usd > another_currency.value_in_usd:
            return f"{self._name} is more valuable than {another_currency.name}."
        elif self._value_in_usd < another_currency.value_in_usd:
