One of the easiest ways to find the median without sorting the array is by using the quickselect algorithm, which is an in-place version of the quicksort's partitioning algorithm. Below is a Python program which solves the problem.

```Python
def partition(nums, low, high):
    pivot = nums[(low + high) // 2]
    while low <= high:
        while nums[low] < pivot:
            low += 1
        while nums[high] > pivot:
            high -= 1
        if low <= high:
            nums[low], nums[high] = nums[high], nums[low]
            low, high = low + 1, high - 1
    return low

def quickselect(nums, k):
    if len(nums) == 1:
        return nums[0]
    select_from = partition(nums, 0, len(nums)-1)
    if select_from == k:
        return nums[select_from]
    elif select_from > k :
        return quickselect(nums[:select_from], k)
    else:
        return quickselect(nums[select_from:], k - select_from)

def find_median(nums):
    if len(nums) % 2 == 1:
        return quickselect(nums, len(nums) // 2)
