Here is a Python solution using recursion to handle the nested dictionaries.

```python
def extract_values(dictionary):
    values_list = []

    # Iterate over items in the dictionary
    for key, value in dictionary.items():
        if isinstance(value, dict):
            # If value is a dictionary, recursively extract values
            values_list.extend(extract_values(value))
        elif isinstance(value, list):
            # If value is a list, iterate over its elements
            for elem in value:
                if isinstance(elem, dict):
                    # If element is a dictionary, recursively extract values
                    values_list.extend(extract_values(elem))
                else:
                    # If element is not a dictionary, add it to the list
                    values_list.append(elem)
        else:
            values_list.append(value)

    return tuple(values_list)

