function nthLongestString(s, n) {
  // split the string into words
  let words = s.split(' ');
  // sort the words by their length in descending order
  let sortedWords = words.sort((a, b) => b.length - a.length);
  // return the nth longest word if exists, otherwise return 'Invalid'
