For this task, we will add an additional function to gather statistical insights from the sorted data array like: median, mean, mode etc. Here is how we do it:

```C++
#include<bits/stdc++.h>
using namespace std;

void bubbleSort(int array[], int n) {
    for(int i = 0; i < n-1; i++) {
        for (int j = 0; j < n-i-1; j++) {
            if (array[j] > array[j+1]) {
                swap(array[j], array[j+1]);
            }
        }
    }
}

void printArray(int array[], int size) {
    int i;
    for (i = 0; i < size; i++)
        cout << array[i] << " ";
    cout << endl;
}

// Function to calculate Mean
double findMean(int a[], int n) {
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += a[i];
    }   
    return (double)sum/(double)n;
}

// Function to calculate median
double findMedian(int a[], int n) {
    if (n % 2 != 0) {
        return (double)a[n/2];
    }
    return (double)(a[(n-1)/2] + a[n/2])/2.0;
}

// Function to calculate mode
int findMode(int a[], int n) {
    int maxCount = 0;
    int mode = a[0];
    int currCount = 1;

    for (int i = 1; i < n; i++) {
        if (a[i] == a[i-1]) {
            currCount++;
        } else if (currCount > maxCount) {
            maxCount = currCount;
            mode = a[i-1];
            currCount = 1;
        }
    }

    // If last element is most frequent
    if (currCount > maxCount) {
        maxCount = currCount;
        mode = a[n-1];
    }

    return mode;
}

int main() {
    int data[] = {3, 7, 1, 2, 8, 6, 9};
    int n = sizeof(data) / sizeof(data[0]);
    bubbleSort(data, n);
    cout << "Sorted array: \n";
    printArray(data, n);
    cout<<"Mean of array is "<<findMean(data,n)<<endl;
    cout<<"Median of array is "<<findMedian(data,n)<<endl;
    cout<<"Mode of array is "<<findMode(data,n)<<endl;
    return 0;
}
```

This program demonstrates how bubble sort can be used to arrange data in a way that simplifies finding the mean, median, and mode of an array of integers. After sorting the array with bubble sort, it will be in ascending order.

The mean is calculated by summing all the numbers and dividing by the number of numbers, the median is calculated by finding the middle number if the total number is odd or the average of the two middle numbers if the total number is even, and the mode is calculated by counting the number of times each number appears in the sorted array and returning the number that appears the most.

