def run_prime_factorization(max_number: int):

    from math import sqrt



    ans = dict()

    remain = max_number



    for j in range(2, int(sqrt(max_number)) + 1):

        if remain % j == 0:

            count = 0



            while remain % j == 0:

                count += 1

                remain //= j



            ans[j] = count



    if remain != 1:

        ans[remain] = 1



    return ans





