def combine_dicts(dict1, dict2):
    combined = {**dict1}  # Copy dict1 into the combined so that the original dictionary does not change

    for key, value in dict2.items():
        if key in dict1:
            if type(value) not in (int, float, str, dict):
                raise ValueError("Unsupported value type: {}".format(type(value)))

            if isinstance(dict1[key], dict) and isinstance(value, dict):
                # Recursive call when values for the same key in both dict1 and dict2's are dictionaries
                combined[key] = combine_dicts(dict1[key], value)
            else:
                # Handles the rest of the cases, string concatenation and numerical addition.
                combined[key] = dict1[key] + value
        else:
            combined[key] = value

    return combined
```

