This code uses nested loops to check horizontally, vertically and diagonally for the occurrence of the word in the 2D array.

```cpp
#include <iostream>
#include <vector>

using namespace std;

void findWord(vector<vector<char>> &grid, const string &word) {
    int rows = grid.size();
    int cols = grid[0].size();
    int len = word.length();
    int x1 = -1, y1 = -1, x2 = -1, y2 = -1;

    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            // Search horizontally
            if (j <= cols - len) {
                int k;
                for (k = 0; k < len; ++k)
                    if (grid[i][j + k] != word[k])
                        break;
                if (k == len) {
                    x1 = i;
                    y1 = j;
                    x2 = i;
                    y2 = j + len - 1;
                }
            }

            // Search vertically
            if (i <= rows - len) {
                int k;
                for (k = 0; k < len; ++k)
                    if (grid[i + k][j] != word[k])
                        break;
                if (k == len) {
                    x1 = i;
                    y1 = j;
                    x2 = i + len - 1;
                    y2 = j;
                }
            }

            // Search diagonally
            if (i <= rows - len && j <= cols - len) {
                int k;
                for (k = 0; k < len; ++k)
                    if (grid[i + k][j + k] != word[k])
                        break;
                if (k == len) {
                    x1 = i;
                    y1 = j;
                    x2 = i + len - 1;
                    y2 = j + len - 1;
                }
            }
        }
    }

    if(x1!=-1 && y1!=-1){  //Checking if word was found
        cout<< "Word found starting at ("<< x1<< ","<< y1<< ") and ending at ("<< x2<< ","<< y2<< ")"<< endl;
    }
    else{
        cout<<"Word not found"<<endl;
    }
}

int main() {
