                                {'a', 'p', 'p', 'l', 'i'},
                                {'a', 'p', 'p', 'l', 'i'},
                                {'a', 'p', 'p', 'l', 'i'},
                                {'a', 'p', 'p', 'l', 'i'} };

  string word = "application";

  findWord(grid, word);

  return 0;
}
