def fibonacci_search(arr, x, n):
    fib_num_minus_2 = 0
    fib_num_minus_1 = 1
    fib_num = fib_num_minus_2 + fib_num_minus_1
    while fib_num < n:
        fib_num_minus_2 = fib_num_minus_1
        fib_num_minus_1 = fib_num
        fib_num  = fib_num_minus_2 + fib_num_minus_1
    offset = -1; 
    while (fib_num > 1):
