            fib_num = fib_num_minus_1
            fib_num_minus_1 = fib_num_minus_2
            fib_num_minus_2 = fib_num - fib_num_minus_1
        elif (arr[i] > x):
            fib_num = fib_num_minus_2
            fib_num_minus_1 = fib_num - fib_num_minus_2
            fib_num_minus_2 = fib_num_minus_1 - fib_num
