def add_to_sorted(array, item):
    # Confirm array is not empty
    if array is None or len(array) == 0:
        raise ValueError("Array must not be empty")

    array.sort()

    if isinstance(item, list):
        for i in item:
            _insert(array, i)
    else:
        _insert(array, item)

    return array

def _insert(array, item):
    pos = 0
    if isinstance(item, int):
        for i, val in enumerate(array):
            if val > item:
                pos = i
                break
        else:
            pos = len(array)
    elif isinstance(item, str):
        for i, val in enumerate(array):
            if str(val) > str(item):
                pos = i
                break
        else:
            pos = len(array)
    array.insert(pos, item)

# Test Cases
print(add_to_sorted([1, 3, 5, 6], 4)) # Output: [1, 3, 4, 5, 6]
print(add_to_sorted([1, 3, 5, 6], [2, 7])) # Output: [1, 2, 3, 5, 6, 7]
print(add_to_sorted(["apple", "banana", "peach"], "cherry")) # Output: ['apple', 'banana', 'cherry', 'peach']
print(add_to_sorted(["apple", "banana", "peach"], ["cherry", "apricot"])) # Output: ['apricot', 'apple', 'banana', 'cherry', 'peach']
print(add_to_sorted([1, 3, 5, "apple", "banana"], [2, "peach"])) # Output: [1, 2, 3, 5, 'apple', 'banana', 'peach']
```

