import sys





class Node(object):

    __slots__ = ('data', 'left', 'right')



    def __init__(self, data):

        self.data = data

        self.left, self.right = None, None



    def insert(self, data):

        """

        insert data according to BST rules

        """

        if data < self.data:

            if not self.left:

                self.left = Node(data)

            else:

                self.left.insert(data)

        # insert duplicate value to right

        else:

            if not self.right:

                self.right = Node(data)

            else:

                self.right.insert(data)



        return self.data



    def find(self, data, parent=None):

        """

        find node with given data

        tree walk as insert goes

        """

        if data < self.data:

            if not self.left:

                return None, None

            return self.left.find(data=data, parent=self)

        elif data > self.data:

            if not self.right:

                return None, None

            return self.right.find(data=data, parent=self)

        else:

            return self, parent



    def children_count(self):

        """

        for choosing node deleting strategy

        """

        cnt = 0

        if self.left:

            cnt += 1

        if self.right:

            cnt += 1

        return cnt



    def delete(self, data):

        """

        delete node with given data

        """

        node, parent = self.find(data)

        if node:

            children_count = node.children_count()

            if children_count == 0:

                # delete reference to parent

                if parent.left is node:

                    parent.left = None

                else:

                    parent.right = None

                del node

            elif children_count == 1:

                # node's son becomes parents' son

                if node.left:

                    n = node.left

                else:

                    n = node.right

                if parent:

                    if parent.left is node:

                        parent.left = n

                    else:

                        parent.right = n

                del node

            else:

                # current node has two real children

                # while the real successor couldn't have two real children

                successor = node.right

                while successor.left:

                    successor = successor.left

                copy_data = successor.data

                self.delete(copy_data)

                node.data = copy_data





def pre_order(node):

    if node:

        print('', node.data, end='')

        pre_order(node.left)

        pre_order(node.right)

    return None





def in_order(node):

    if node:

        in_order(node.left)

        print('', node.data, end='')

        in_order(node.right)

    return None





