```java
public class MatrixOperation {
    public void rotateMatrix(char[][] matrix) throws Exception {
        if (!isSquare(matrix)) {
            throw new Exception("The matrix is not a square matrix.");
        }
        int n = matrix.length;
        for (int i = 0; i < n/2; i++) {
            for (int j = i; j < n - i - 1; j++) {
                char temp = matrix[i][j];
                matrix[i][j] = matrix[j][n - 1 - i];
                matrix[j][n - 1 - i] = matrix[n - 1 - i][n - 1 - j];
                matrix[n - 1 - i][n - 1 - j] = matrix[n - 1 - j][i];
                matrix[n - 1 - j][i] = temp;
            }
        }
    }

    public void transposeMatrix(char[][] matrix) throws Exception {
        if (!isSquare(matrix)) {
            throw new Exception("The matrix is not a square matrix.");
        }
        int n = matrix.length;
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                char temp = matrix[i][j];
                matrix[i][j] = matrix[j][i];
                matrix[j][i] = temp;
            }
        }
    }

    public void reflectMatrix(char[][] matrix, boolean horizontally) throws Exception {
        if (!isSquare(matrix)) {
            throw new Exception("The matrix is not a square matrix.");
        }
        int n = matrix.length;
        if (horizontally) {
            for (int i = 0; i < n/2; i++) {
                for (int j = 0; j < n; j++) {
                    char temp = matrix[i][j];
                    matrix[i][j] = matrix[n - 1 - i][j];
                    matrix[n - 1 - i][j] = temp;
                }
            }
        } else {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n/2; j++) {
                    char temp = matrix[i][j];
                    matrix[i][j] = matrix[i][n - 1 - j];
                    matrix[i][n - 1 - j] = temp;
                }
            }
        }
    }

    public boolean isSquare(char[][] matrix) {
        int rows = matrix.length;
        for (char[] row : matrix) {
            if (row.length != rows) {
                return false;
            }
        }
        return true;
    }
}
```
