Now, you can define the doubly linked list class and the functions you need:

```python
class DoublyLinkedList:
    def __init__(self):
        self.head = None

    def insert(self, data, position):
        new_node = Node(data)
        if position < 0:
            return 'Error: Position must be positive'
        if self.head is None:  
            if position == 0:
                self.head = new_node
            else:
                return 'Error: Position out of bounds'
        else: 
            if position == 0:
                new_node.next = self.head
                self.head.prev = new_node
                self.head = new_node
            else: 
                temp = self.head
                for _ in range(position - 1):
                    if temp.next is None:
                        return 'Error: Position out of bounds'
                    temp = temp.next
                if temp.next is None:
                    temp.next = new_node
                    new_node.prev = temp
                else: 
                    new_node.next = temp.next
                    new_node.prev = temp
                    temp.next.prev = new_node
                    temp.next = new_node

    def delete(self, position):
        if self.head is None:
            return 'Error: List is empty'
        if position < 0:
            return 'Error: Position must be positive'
        temp = self.head
        if position == 0:
            self.head = temp.next
            if temp.next is not None:
                temp.next.prev = None
        else:
            for _ in range(position):
                if temp.next is None:
                    return 'Error: Position out of bounds'
                temp = temp.next
            temp.prev.next = temp.next
            if temp.next is not None:
                temp.next.prev = temp.prev

    def print_list(self):
        temp = self.head
        while(temp):
            print(temp.data, end = " ")
            temp = temp.next
        print()

