forward_search_range(regex_t* reg, const UChar* str, const UChar* end, UChar* s,
		     UChar* range, UChar** low, UChar** high, UChar** low_prev)
{
  UChar *p, *pprev = (UChar* )NULL;

#ifdef ONIG_DEBUG_SEARCH
  fprintf(stderr, "forward_search_range: str: %d, end: %d, s: %d, range: %d\n",
	  (int )str, (int )end, (int )s, (int )range);
#endif

  p = s;
  if (reg->dmin > 0) {
    if (ONIGENC_IS_SINGLEBYTE(reg->enc)) {
      p += reg->dmin;
    }
    else {
      UChar *q = p + reg->dmin;

      if (q >= end) return 0; /* fail */
      while (p < q) p += enclen(reg->enc, p);
    }
  }

 retry:
  switch (reg->optimize) {
  case ONIG_OPTIMIZE_EXACT:
    p = slow_search(reg->enc, reg->exact, reg->exact_end, p, end, range);
    break;
  case ONIG_OPTIMIZE_EXACT_IC:
    p = slow_search_ic(reg->enc, reg->case_fold_flag,
                       reg->exact, reg->exact_end, p, end, range);
    break;

  case ONIG_OPTIMIZE_EXACT_BM:
    p = bm_search(reg, reg->exact, reg->exact_end, p, end, range);
    break;

  case ONIG_OPTIMIZE_EXACT_BM_NOT_REV:
    p = bm_search_notrev(reg, reg->exact, reg->exact_end, p, end, range);
    break;

  case ONIG_OPTIMIZE_MAP:
    p = map_search(reg->enc, reg->map, p, range);
    break;
  }

  if (p && p < range) {
    if (p - reg->dmin < s) {
    retry_gate:
      pprev = p;
      p += enclen(reg->enc, p);
      goto retry;
    }

    if (reg->sub_anchor) {
      UChar* prev;

      switch (reg->sub_anchor) {
      case ANCHOR_BEGIN_LINE:
        if (!ON_STR_BEGIN(p)) {
          prev = onigenc_get_prev_char_head(reg->enc,
                                            (pprev ? pprev : str), p);
          if (!ONIGENC_IS_MBC_NEWLINE(reg->enc, prev, end))
            goto retry_gate;
        }
        break;

      case ANCHOR_END_LINE:
        if (ON_STR_END(p)) {
#ifndef USE_NEWLINE_AT_END_OF_STRING_HAS_EMPTY_LINE
          prev = (UChar* )onigenc_get_prev_char_head(reg->enc,
                                                     (pprev ? pprev : str), p);
          if (prev && ONIGENC_IS_MBC_NEWLINE(reg->enc, prev, end))
            goto retry_gate;
#endif
        }
        else if (! ONIGENC_IS_MBC_NEWLINE(reg->enc, p, end)
#ifdef USE_CRNL_AS_LINE_TERMINATOR
                 && ! ONIGENC_IS_MBC_CRNL(reg->enc, p, end)
#endif
                 )
          goto retry_gate;
        break;
      }
    }

    if (reg->dmax == 0) {
      *low = p;
      if (low_prev) {
        if (*low > s)
          *low_prev = onigenc_get_prev_char_head(reg->enc, s, p);
        else
          *low_prev = onigenc_get_prev_char_head(reg->enc,
                                                 (pprev ? pprev : str), p);
      }
    }
    else {
      if (reg->dmax != ONIG_INFINITE_DISTANCE) {
        *low = p - reg->dmax;
        if (*low > s) {
          *low = onigenc_get_right_adjust_char_head_with_prev(reg->enc, s,
                                          *low, (const UChar** )low_prev);
          if (low_prev && IS_NULL(*low_prev))
            *low_prev = onigenc_get_prev_char_head(reg->enc,
                                                   (pprev ? pprev : s), *low);
        }
        else {
          if (low_prev)
            *low_prev = onigenc_get_prev_char_head(reg->enc,
                                                   (pprev ? pprev : str), *low);
        }
      }
    }
    /* no needs to adjust *high, *high is used as range check only */
    *high = p - reg->dmin;

#ifdef ONIG_DEBUG_SEARCH
    fprintf(stderr,
    "forward_search_range success: low: %d, high: %d, dmin: %d, dmax: %d\n",
	    (int )(*low - str), (int )(*high - str), reg->dmin, reg->dmax);
#endif
    return 1; /* success */
  }

  return 0; /* fail */
}

In Objective-C, we could use the following code to construct a ternary tree. Here, we first define data structure for the node, and then we implement a depth-first search (DFS) to form the node. For the DFS, we initiate the tree's root as null and then adding nodes based on a search comparison. If the incoming value is less than the current value, we move to the left; if it's equal, we move to the middle; otherwise we move to the right. As a result, we effectively sort out the nodes.

Objective-C code:

```Objective-C
// Define a node
@interface Node : NSObject
@property (assign) int value;
@property (strong) Node *leftChild, *middleChild, *rightChild;
@end

@implementation Node
@end

// Define tree
@interface TernaryTree : NSObject
@property (strong) Node *root;
- (void)addValue:(int)value;
- (Node *)addValue:(int)value toNode:(Node *)node;
@end

@implementation TernaryTree
- (void)addValue:(int)value {
    self.root = [self addValue:value toNode:self.root];
}

- (Node *)addValue:(int)value toNode:(Node *)node {
    if (node == nil) {
        node = [Node new];
        node.value = value;
    } else if (value < node.value) {
        node.leftChild = [self addValue:value toNode:node.leftChild];
    } else if (value == node.value) {
        node.middleChild = [self addValue:value toNode:node.middleChild];
    } else {
        node.rightChild = [self addValue:value toNode:node.rightChild];
    }
    return node;
}
@end

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        TernaryTree *tree = [TernaryTree new];
        [tree addValue:13];
        [tree addValue:7];
        [tree addValue:6];
        [tree addValue:15];
        [tree addValue:19];
        [tree addValue:4];
        [tree addValue:9];
        [tree addValue:22];
        [tree addValue:1];
        [tree addValue:11];
        [tree addValue:3];
    }
    return 0;
}
```

The computational complexity for adding an element in this ternary tree is O(log n) in the average case, and O(n) in the worst case (the elements are inserted in a sorted order causing the tree to be imbalanced), where n is the number of nodes in the tree. This is because each comparison allows us to skip over half of the tree (average case), hence giving us a logarithmic time complexity. For worst case, the insert operation could potentially require us to travel from the root to the leaf node, giving us a linear time complexity.

