Here is a C++ program that can find the longest common substring from two given strings that differ by at most k characters. This program contains a function `LCSubStr()` which determines the longest common substring between two input strings considering the threshold `k`. The function uses dynamic programming approach.

```cpp
#include<bits/stdc++.h> 
using namespace std; 

int min(int a, int b) {
    if(a < b)
        return a;
    else
        return b;
}

int LCSubStr(string X, string Y, int m, int n, int k) 
{ 
    int result = 0;  
    int len[m+1][n+1];

    for (int i = 0; i <= m; i++) { 
        for (int j = 0; j <= n; j++) { 
            if(i==0||j==0)
                len[i][j] = 0; 
            else if(tolower(X[i - 1]) == tolower(Y[j - 1])) { 
                len[i][j] = len[i-1][j-1] + 1; 
                if(len[i][j]>result)
                    result=len[i][j]; 
            } 
            else if(len[i-1][j-1] + 1 > k) {
                len[i][j] = min(len[i][j-1], len[i-1][j]);
                if(len[i][j]>result)
                    result=len[i][j]; 
            }
            else
                len[i][j] = 0;
        } 
    } 

    return result; 
} 

int main() 
{ 
    string X = "stackoverflow";  
    string Y = "overburning"; 
    int m = X.size(); 
    int n = Y.size(); 
    int k = 2;
    cout<<"Length of Longest Common Substring is "<<LCSubStr(X, Y, m, n, k); 
    return 0; 
} 
```
Please note that the question requests for the longest common substring, not subsequence. A substring differs from subsequence in that the characters in the substring must be consecutive characters in the original string. This code solves for a common substring under parameters given in the question.

