function fibonacci(y, memo = {}) {
    // Validate the input
    if (typeof y !== 'number' || y < 0 || y > 50) {
        throw new Error("The input should be a positive integer less than or equal 50");
    }
    // Base cases
    if (y === 0) return 0;
    if (y === 1) return 1;
    // check if we already calculated this value before
    if (memo[y]) return memo[y];
    // Otherwise calculate it and store it in the memo object
    memo[y] = fibonacci(y - 1, memo) + fibonacci(y - 2, memo);
    return memo[y];
}

