Here is an example of how one might add user authentication to this Node.js script. This modification uses JSON Web Tokens for authentication. Before sending back the list of all users, it verifies the token sent in the header of the request.

Here, we are using 'jsonwebtoken' and 'bcryptjs' npm packages for token generation and password hashing. Make sure these packages are installed in your system. If not, install using npm i jsonwebtoken bcryptjs.

The 'userModel' has the schema of the user which includes fields like name, email, password, and tokens. The users in the database collection should be stored with hashed passwords and not the original ones.

``` JavaScript
const jwt = require('jsonwebtoken');
const User = require('./models/userModel');

const getAllUsers = async (req, res) => {
  try {
    const token = req.header('Authorization').replace('Bearer ', '');
    const decoded = jwt.verify(token, 'YOUR_SECRET_KEY'); // replace 'YOUR_SECRET_KEY' with an actual secret string
    const user = await User.findOne({_id: decoded._id, 'tokens.token': token});

    if (!user) {
      throw new Error();
    }

    User.find()
      .then((users) => {
        res.json(users);
      })
      .catch((err) => {
        console.log(err);
        res.status(500).send();
      });
  } catch(e) {
    res.status(401).send({ error: 'Please authenticate.' });
  };
};
```
In a real application setting, the 'YOUR_SECRET_KEY' would not be hardcoded in the verify function. It would instead be stored in environment variables or other protected means, to ensure it is not exposed or leaked.

The middleware verifies the token and if the token is not valid or expired, it will return a status of 401 and message as 'Please authenticate.'. If the token is valid, next middleware in line will be called. In this case 'User.find()' will be executed and list of users will be returned.

layer_resize(int layer, int x_size, int y_size)
{
	int                 old_height;
	int                 old_width;
	struct map_tile*    tile;
	int                 tile_width;
	int                 tile_height;
	struct map_tile*    tilemap;
	struct map_trigger* trigger;
	struct map_zone*    zone;
	size_t              tilemap_size;

	int x, y, i;

	old_width = s_map->layers[layer].width;
	old_height = s_map->layers[layer].height;

	// allocate a new tilemap and copy the old layer tiles into it.  we can't simply realloc
	// because the tilemap is a 2D array.
	tilemap_size = x_size * y_size * sizeof(struct map_tile);
	if (x_size == 0 || tilemap_size / x_size / sizeof(struct map_tile) != y_size
		|| !(tilemap = malloc(tilemap_size)))
		return false;
	for (x = 0; x < x_size; ++x) {
		for (y = 0; y < y_size; ++y) {
			if (x < old_width && y < old_height) {
				tilemap[x + y * x_size] = s_map->layers[layer].tilemap[x + y * old_width];
			}
			else {
				tile = &tilemap[x + y * x_size];
				tile->frames_left = tileset_get_delay(s_map->tileset, 0);
				tile->tile_index = 0;
			}
		}
	}

	// free the old tilemap and substitute the new one
	free(s_map->layers[layer].tilemap);
	s_map->layers[layer].tilemap = tilemap;
	s_map->layers[layer].width = x_size;
	s_map->layers[layer].height = y_size;

	// if we resize the largest layer, the overall map size will change.
	// recalcuate it.
	tileset_get_size(s_map->tileset, &tile_width, &tile_height);
	s_map->width = 0;
	s_map->height = 0;
	for (i = 0; i < s_map->num_layers; ++i) {
		if (!s_map->layers[i].is_parallax) {
			s_map->width = fmax(s_map->width, s_map->layers[i].width * tile_width);
			s_map->height = fmax(s_map->height, s_map->layers[i].height * tile_height);
		}
	}

	// ensure zones and triggers remain in-bounds.  if any are completely
	// out-of-bounds, delete them.
	for (i = (int)vector_len(s_map->zones) - 1; i >= 0; --i) {
		zone = vector_get(s_map->zones, i);
		if (zone->bounds.x1 >= s_map->width || zone->bounds.y1 >= s_map->height)
			vector_remove(s_map->zones, i);
		else {
			if (zone->bounds.x2 > s_map->width)
				zone->bounds.x2 = s_map->width;
			if (zone->bounds.y2 > s_map->height)
				zone->bounds.y2 = s_map->height;
		}
	}
	for (i = (int)vector_len(s_map->triggers) - 1; i >= 0; --i) {
		trigger = vector_get(s_map->triggers, i);
		if (trigger->x >= s_map->width || trigger->y >= s_map->height)
			vector_remove(s_map->triggers, i);
	}

	return true;
}

