```javascript
function parseXml(xmlStr) {
    let parser = new DOMParser();
    let xmlDoc = parser.parseFromString(xmlStr, "text/xml");

    let root = xmlDoc.children[0];
    let peopleNode = root.children[0];
    let people = Array.from(peopleNode.children).map(personNode => {
        return {
            name: personNode.children[0].textContent,
            age: personNode.children[1].textContent
        };
    });

    return { root: { people: people} };
}

