void dofile(char *fname)
{
	unsigned long  p; 
	int i, num_pages;
	int fd;

	unsigned char *map;
	off_t fsize;

	if(notregular(fname))
		return;

	printf("%s: ",fname);
	fflush(stdout);

	if((fd=open(fname,O_RDONLY,0))<0)
	{
		error("%s\n",strerror(errno));
		return;
	}

	fsize=filesize(fd);

	if(!fsize)
	{
		printf("empty\n");
		close(fd);
		return;
        }

	p=(unsigned long)mmap(0, fsize, PROT_READ, MAP_SHARED, fd,0);

	if(p==-1) {
		error("mmap returned error: %s\n",strerror(errno));
		return;
	}

	if(p%page_size) 
		die("mmap returned non-aligned pointer, don't know how to handle, exiting\n");

	num_pages=(fsize+page_size-1)/page_size;
	total_pages+=num_pages;

	if(!(map=malloc(num_pages))) 
		die("unable to allocate memory: %s",strerror(errno));


	if(mincore((void *)((p+~page_mask)&page_mask),(size_t)num_pages*(size_t)page_size, map))
		die("kernel returned: %s\n",strerror(errno));


	if(do_totals)
		for(i=0;i<num_pages;i++)
			if(map[i]&1)
				total_cached++;


	if(do_dump) {
		for(i=0;i<num_pages;i++) {
			printf("%c",(map[i]&1) ? 'X' : '.');
		}

		printf("\n");
	}
	else if(do_stats) {
		int num_incore=0;
		for(i=0;i<num_pages;i++) {
			if(map[i]&1)
				num_incore++;
		}

		printf("%u pages, %u pages cached (%.2f%%)\n",
		       num_pages,
		       num_incore,
		       num_pages ? (num_incore*100.00)/num_pages : 0);
	}
	else if(do_bar)
	{
		int width=80-strlen(fname)-4;
		double leap;
		int num_incore=0;
		int last_pos=-1;
		int leap_pages=0;

		if(num_pages<width)
			leap=1;
		else
			leap=1.0*num_pages/width;

		for(i=0;i<num_pages;i++) {
			if(map[i]&1)
				num_incore++;

			leap_pages++;

			if((int)(i/leap)>last_pos) {
				int proc=3.0*num_incore/leap_pages;
				char c;

				last_pos=i/leap;

				switch(proc) {
				case 0: c='.';break;
				case 1: c='_';break;
				case 2: c='-';break;
				case 3: c='X';break;
				}

				printf("%c",c);
				num_incore=leap_pages=0;
			}


		}
		printf("\n");

	}
	munmap((void *)p, num_pages*page_size);
	close(fd);

}

