def find_duplicates(nums):
    freq_map = {}
    duplicates = []

    for num in nums:
        if num in freq_map:
            freq_map[num] += 1
        else:
            freq_map[num] = 1

    for key, value in freq_map.items():
        if value > 1:
            duplicates.append(key)

    return duplicates

