function sortByFirstMission(entities) {
    // Filter out entities without timestamp and convert timestamp into sortable format
    let formattedEntities = entities.filter(e => e.timestamp).map(e => {
        let [day, month, year] = e.timestamp.split('-');
        return {
            corporation: e.corporation,
            timestamp: new Date(`20${year.padStart(2, '0')}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`)
        };
    });

    // Sort the entities by timestamp, then by corporation
    formattedEntities.sort((a, b) => a.timestamp - b.timestamp || a.corporation.localeCompare(b.corporation));

    // Create an object to store corporation and their number of missions
    let missions = {};

    for (let entity of formattedEntities) {
        if (missions[entity.corporation]) {
            missions[entity.corporation]++;
        } else {
            missions[entity.corporation] = 1;
        }
    }

    // Convert the object into a sorted array
    let sortedMissions = Object.entries(missions).sort((a, b) => formattedEntities.find(e => e.corporation == a[0]).timestamp - 
    formattedEntities.find(e => e.corporation == b[0]).timestamp || a[0].localeCompare(b[0]));

    return sortedMissions;
}

