```javascript
class Task {
    constructor(id, status, priority, completion) {
        this.id = id;
        this.status = status;
        this.priority = priority;
        this.completion = completion;
        this.subTasks = [];
    }

    addSubTask(subTask) {
        this.subTasks.push(subTask);
    }

    removeSubTask(subTaskId) {
        this.subTasks = this.subTasks.filter(subTask => subTask.id !== subTaskId);
    }

    getSubTask(subTaskId) {
        return this.subTasks.find(subTask => subTask.id === subTaskId);
    }

    updateCompletion() {
        let totalCompletion = 0;
        this.subTasks.forEach(subTask => {
            totalCompletion += subTask.completion;
        });
        this.completion = totalCompletion / this.subTasks.length;
    }
}

class TaskManager {
    constructor() {
        this.tasks = [];
    }

    addTask(task) {
        this.tasks.push(task);
    }

    filterTasksByPriority(priority) {
        return this.tasks.filter(task => task.priority === priority);
    }

    filterTasksByStatus(status) {
        return this.tasks.filter(task => task.status === status);
    }

    getTask(taskId) {
        return this.tasks.find(task => task.id === taskId);
    }

    reassignSubTask(currentTaskId, targetTaskId, subTaskId) {
        let currentTask = this.getTask(currentTaskId);
        let subTask = currentTask.getSubTask(subTaskId);
        currentTask.removeSubTask(subTaskId);
        let targetTask = this.getTask(targetTaskId);
        targetTask.addSubTask(subTask);
    }
}
```

