def is_leap_year(year, calendar='Gregorian'):
    """Check if a given year is a leap year."""
    if calendar == 'Gregorian':
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
    elif calendar == 'Julian':
        return year % 4 == 0
    else:
        raise ValueError("Invalid calendar. Only 'Gregorian' and 'Julian' are supported.")

def main():
    year = input("Enter a year: ")
    calendar = input("Enter a calendar (Gregorian or Julian): ")

    # Handling invalid inputs
    try:
        year = int(year)
        assert year > 0, "Please enter a positive year."

        if calendar not in ['Gregorian', 'Julian']:
            raise ValueError("Please choose either 'Gregorian' or 'Julian' calendar.")

        leap_year = is_leap_year(year, calendar)
    except ValueError as e:
        print("Invalid input. Please enter an integer for the year and choose the correct calendar.")
        print(str(e))
    except AssertionError as e:
        print(str(e))

    # Display the result
    else:
        if leap_year:
            print(year, "is a leap year in the", calendar, "calendar.")
        else:
            print(year, "is not a leap year in the", calendar, "calendar.")

if __name__ == "__main__":
