Here is a JavaScript function for turning the HTML table into JSON format. This solution uses DOM parsing to iterate over the tables and rows, creating JSON as needed.

```javascript
function tableToJson(tableId) {
    // initialize variables
    var table = document.getElementById(tableId);
    var rows = table.rows;
    var headers = [];
    var data = [];

    // Get headers from first row
    for (var i=0; i<rows[0].cells.length; i++) {
        headers[i] = rows[0].cells[i].innerHTML;
    }

    // get rest of the table data
    for (var i=1; i<rows.length; i++) {
        var tableRow = rows[i];
        var rowData = {};

        for (var j=0; j<tableRow.cells.length; j++) {
            rowData[ headers[j] ] = tableRow.cells[j].innerHTML;
        }

        data.push(rowData);
    }

    // return as JSON
    return JSON.stringify(data);
}

