class Employee:
  def __init__(self, employeeID, name, tenure):
    self.employeeID = employeeID
    self.name = name
    self.tenure = tenure

  def calculate_pension(self):
    try:
      if self.tenure <= 0:
        return "Tenure should be a positive value!"
      elif self.tenure < 5 :
        return self.tenure * 1000 
      elif self.tenure >= 5:
        return self.tenure * 2000
    except TypeError:
      return "Invalid input. Tenure should be a number!"

  def validate(self):
    if not isinstance(self.employeeID, int) or not isinstance(self.name, str) or not isinstance(self.tenure, (int, float)):
