        if name not in self.candidates:
            self.candidates[name] = 0
        else:
            print("Candidate already exists.")

    def remove_candidate(self, name):
        if name in self.candidates:
            del self.candidates[name]
        else:
            print("Candidate not found.")

    def add_votes(self, location_data):
        for candidate, votes in location_data.items():
            if candidate in self.candidates:
                self.candidates[candidate] += votes
            else:
                print("Candidate not found in the list. Please add before registering votes.")

