def dfs(x, order, edges, visited):

  visited[x] = True

  for e in edges[x]:

    if not visited[e]:

      dfs(e, order, edges, visited)

  order.append(x)



def dfs_rev(x, rev_edges, visited):

  visited[x] = True

  ret = 0

  for e in rev_edges[x]:

    if not visited[e]:

      ret += 1

      ret += dfs_rev(e, rev_edges, visited)

  return ret





