function concatStrings(a, b) {
    //check if the inputs are either null or undefined or aren't strings
    if (a === null || a === undefined || typeof a !== 'string' ||
        b === null || b === undefined || typeof b !== 'string') {
        return "Error: Inputs should be strings and not null nor undefined";
    }

    let stringArrayA = Array.from(a);
    let stringArrayB = Array.from(b);

    let stringArrayAB = [...stringArrayA, ...stringArrayB];
    let concatenatedString = stringArrayAB.toString().replace(/,/g, ''); 

