Below is a Python script that demonstrates a recursive way of generating a Fibonacci series up to a particular user-input ordinal number. The script receives the user input, calls a recursive function to generate a Fibonacci series, and prints the sequence.

```python
def fibonacci_sequence(n):
    if n <= 0:
        return []
    elif n == 1:
        return [0]
    elif n == 2:
        return [0, 1]
    else:
        sequence = fibonacci_sequence(n - 1)
        sequence.append(sequence[-1] + sequence[-2])
        return sequence

def main():
    n = int(input("Enter the ordinal number up to which the Fibonacci sequence should be displayed: "))
    if n > 0:
        sequence = fibonacci_sequence(n)
        print(f"The Fibonacci sequence up to the {n}th ordinal number is: {sequence}")
    else:
        print("Invalid input, enter a positive integer!")

if __name__ == "__main__":
    main()
```

