def pig_latin_translator(sentence):
    words = sentence.split()
    vowels = 'aeiou'
    transformed_words = []

    for word in words:
        if word[0] in vowels:
            transformed_words.append(word + 'ay')
        else:
            for i, char in enumerate(word):
                if char in vowels:
                    transformed_words.append(word[i:] + word[:i] + 'ay')
                    break

    return ' '.join(transformed_words)


def count_vowels(sentence):
    vowels = 'aeiou'
    count = {v: 0 for v in vowels}

    for char in sentence:
        if char in vowels:
            count[char] += 1

    return count


def handle_punctuation(sentence):
    punctuation_marks = ['.', ',', ';', '!', '?']

    for mark in punctuation_marks:
        sentence = sentence.replace(mark, '')

    return sentence

