class DateCalculator {
    public function printToday() {
        $date = new DateTime();
        echo "今天是 " . $date->format('Y/m/d') . "\n";
    }

    public function calculateDays($inputDate) {
        try {
            $date = DateTime::createFromFormat('Y/m/d', $inputDate);
            if (!$date || $date->format('Y/m/d') !== $inputDate) {
                throw new Exception('无效的日期格式！');
