import java.util.*;

public class Main {
    public static void main(String[] args) {
        String statement = "I am a student";
        System.out.println(getDistinctWords(statement));
    }

    public static List<String> getDistinctWords(String statement) {
        // Split the sentence into words
        String[] words = statement.split(" ");

        // Use a LinkedHashSet to preserve the order and ignore duplicates
        Set<String> distinctWords = new LinkedHashSet<>(Arrays.asList(words));

