二元搜索樹的平衡和排序可以通过AVL树或红黑树等自平衡二叉搜索树实现。这些数据结构在添加、删除节点后能自动平衡，确保树的搜索，插入，删除操作达到均匀的时间复杂度。

下面我将给出一个JavaScript实现的AVL树的示例：

```javascript
class Node {
    constructor(key) {
        this.key = key;
        this.height = 1;
        this.left = null;
        this.right = null;
    }
}

class AVLTree {
    constructor() {
        this.root = null;
    }

    height(node) {
        if(node === null) {
            return 0;
        } else {
            return node.height;
        }
    }

    rotationLL(node) {
        let temp = node.left;
        node.left = temp.right;
        temp.right = node;
        node.height = Math.max(this.height(node.left), this.height(node.right)) + 1;
        temp.height = Math.max(this.height(temp.left), node.height) + 1;
        return temp;
    }

    rotationRR(node) {
        let temp = node.right;
        node.right = temp.left;
        temp.left = node;
        node.height = Math.max(this.height(node.left), this.height(node.right)) + 1;
        temp.height = Math.max(this.height(temp.right), node.height) + 1;
        return temp;
    }

    rotationLR(node) {
        node.left = this.rotationRR(node.left);
        return this.rotationLL(node);
    }

    rotationRL(node) {
        node.right = this.rotationLL(node.right);
        return this.rotationRR(node);
    }

    balance(node) {
        if(this.height(node.left) - this.height(node.right) > 1) {
            if(this.height(node.left.left) >= this.height(node.left.right)) {
                node = this.rotationLL(node);
            } else {
                node = this.rotationLR(node);
            }
        } else if(this.height(node.right) - this.height(node.left) > 1) {
            if(this.height(node.right.right) >= this.height(node.right.left)) {
                node = this.rotationRR(node);
            } else {
                node = this.rotationRL(node);
            }
        }
        node.height = Math.max(this.height(node.left), this.height(node.right)) + 1;
        return node;
    }

    insert(node, key) {
        if(node === null) {
            node = new Node(key);
        } else if(key < node.key) {
            node.left = this.insert(node.left, key);
            node = this.balance(node);
        } else if(key > node.key) {
            node.right = this.insert(node.right, key);
            node = this.balance(node);
        }
        return node;
    }

