This JavaScript function will recursively update the font style to italic for all <p> and <span> elements, and return how many elements were updated.

```javascript
function updateStyleAndCount(node) {
    // Initialize count of updated elements
    let count = 0;

    // Check if node exists and it has child nodes
    if (node && node.childNodes) {
        // Check every child node
        for (let i = 0; i < node.childNodes.length; i++) {
            let childNode = node.childNodes[i];

            // If the current child is a p or span element
            if (childNode.nodeName === 'P' || childNode.nodeName === 'SPAN') {
                // Set the style to italic
                childNode.style.fontStyle = 'italic';

                // Increment the count of updated elements
                count++;
            }

            // Call the function recursively on the current childNode
            count += updateStyleAndCount(childNode);
        }
    }

    return count;
}

