    evens = []
    # Loop through the list
    for i in list:
        # If the number is even, add it to the evens list
        if i % 2 == 0:
            evens.append(i)
    # If there are no even numbers, return a message saying so
    if not evens:
        return "There are no even numbers in the list."
    else:
        # If there are even numbers, return the smallest one
