    def cycle(neighbor, start, ring_size, node):

        visited = [False]*node

        stack = []

        stack.append([start])

        visited[start] = True

        while (stack):

            curr_path = stack.pop()

            #check = deepcopy(curr_path)

            #check = set(check)

            if len(curr_path) > ring_size:

                continue

            # print curr_path

            last = curr_path[-1]

            for nei in neighbor[last]:

                if nei in curr_path:

                    if len(curr_path)==0:

                        continue

                    if (len(curr_path) <= ring_size) and (curr_path[0] == nei):

                        new_path = copy(curr_path)

                        return new_path

                    elif (len(curr_path) <= ring_size):

                        return cycle(neighbor,nei,ring_size-1,node)

                if visited[nei]:

                    continue

                visited[nei] = True

                new_path = copy(curr_path)

                new_path.append(nei)

                stack.append(new_path)

        return -1

    N, M = LI()

