function transformString(str) {
    let transformedStr = '';

    for (let i = 0; i < str.length; i++) {
        // Check if the character is a digit
        if (/\d/.test(str[i])) {
            // Convert the digit to Unicode Character
            transformedStr += String.fromCharCode(str[i]);
        } else if (/[a-zA-Z]/.test(str[i])) {
            // Convert the alphabet to ASCII value
            transformedStr += str[i].charCodeAt(0);
        } else {
            transformedStr += str[i];
        }
        // Add a white-space after each transformation except for the last character
        if (i !== str.length - 1) {
            transformedStr += " ";
        }
    }
    return transformedStr;
}

transformString("7h3y2");  // Returns: "7 104 3 121 2"
```

