function countSubstring(mainStr, subStr) {
  var count = 0;
  var subStrLength = subStr.length;
  for (var i = 0; i < mainStr.length; i++) {
    var currSubstring = '';
    for (var j = i; j < i + subStrLength; j++) {
      currSubstring += mainStr[j];
    }
    if (currSubstring === subStr) {
      count++;
      i += subStrLength - 1;
    }
  }
  return count;
}

