    public static async Task ExtractHyperlinks(string url)
    {
        try
        {
            // 1. 載入網頁
            var htmlDoc = new HtmlDocument();
            var content = await DownloadWebPageAsync(url);
            htmlDoc.LoadHtml(content);

            // 2. 提取並列印出所有超連結
            var aNodes = htmlDoc.DocumentNode.SelectNodes("//a[@href]");
            foreach (var aNode in aNodes)
            {
                var link = aNode.Attributes["href"].Value;
                // 將可能的相對連結轉換為絕對連結
                if (!Uri.IsWellFormedUriString(link, UriKind.Absolute))
                {
                    var baseUri = new Uri(url);
                    var absoluteUri = new Uri(baseUri, link);
                    link = absoluteUri.AbsoluteUri;
                }
                Console.WriteLine(link);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex.Message);
        }
    }

    // 使用 HttpClient 下載網頁
    public static async Task<string> DownloadWebPageAsync(string url)
    {
        try
        {
            return await httpClient.GetStringAsync(url);
        }
        catch (Exception ex)
        {
            throw new Exception($"Failed to download page: {url}", ex);
        }
    }
}
