from collections import Counter





def solve(n, aaa):

    if all(a == 0 for a in aaa):

        return True



    if n % 3 != 0:

        return False



    cnt = Counter(aaa)

    if len(cnt) == 2:

        (a1, c1), (a2, c2) = cnt.most_common()

        if c1 != n * 2 // 3 or c2 != n // 3:

            return False

        return a2 == 0



    if len(cnt) == 3:

        if any(c != n // 3 for c in list(cnt.values())):

            return False

        a1, a2, a3 = list(cnt.keys())

        return a1 ^ a2 == a3



    return False





