Below is the C++ function for calculating median of a vector of double-precision numbers. Note that the function assumed the size of the vector is greater than 0.

```c++
#include <vector>
#include <algorithm>
#include <stdexcept>

double computeMedian(std::vector<double>& nums) {
    if (nums.empty()) {
        throw std::runtime_error("Cannot compute median of an empty vector");
    }

    size_t size = nums.size();
    sort(nums.begin(), nums.end());

    if (size % 2 == 0) {
        // If count of numbers is even, we need to return avg of two middle numbers.
        return (nums[size / 2 - 1] + nums[size / 2]) / 2;
    } 
    else {
        // For odd count, the median is the number in the middle.
        return nums[size / 2];
    }
}

int main() {
    std::vector<double> numArray = {1.5, 3.0, 4.5, 2.5, 5.0};
    double median = computeMedian(numArray);

    std::cout << "Median: " << median << std::endl;

    return 0;
}
```
This code starts by checking if the vector is empty, and then sorts the vector. If the vector has an even number of elements, the function computes the average of the two middle elements. If the vector has an odd number of elements, the function returns the middle element. In both cases, the result is a double-precision floating point number.

static void ffs_user_copy_worker(struct work_struct *work)
{
	struct ffs_io_data *io_data = container_of(work, struct ffs_io_data,
						   work);
	int ret = io_data->req->status ? io_data->req->status :
					 io_data->req->actual;
	bool kiocb_has_eventfd = io_data->kiocb->ki_flags & IOCB_EVENTFD;

	if (io_data->read && ret > 0) {
		use_mm(io_data->mm);
		ret = copy_to_iter(io_data->buf, ret, &io_data->data);
		if (iov_iter_count(&io_data->data))
			ret = -EFAULT;
		unuse_mm(io_data->mm);
	}

	io_data->kiocb->ki_complete(io_data->kiocb, ret, ret);

	if (io_data->ffs->ffs_eventfd && !kiocb_has_eventfd)
		eventfd_signal(io_data->ffs->ffs_eventfd, 1);

	usb_ep_free_request(io_data->ep, io_data->req);

	if (io_data->read)
		kfree(io_data->to_free);
	kfree(io_data->buf);
	kfree(io_data);
}

