def binary_search(arr, low, high, x, calls=0):

    if high >= low: 
        mid = (high + low) // 2
        calls += 1
        if arr[mid] == x:
            return mid, calls 

        elif arr[mid] > x: 
            return binary_search(arr, low, mid - 1, x, calls) 

        else: 
            return binary_search(arr, mid + 1, high, x, calls) 

    else: 
        return -1, calls

