function leastFrequentChar(my_text) {
    let charsCountMap = new Map();
    // This will create a Map with characters as keys and their counts as values
    for(let char of my_text){
        if(char !== ' '){ // skip spaces
            charsCountMap.set(char, (charsCountMap.get(char) || 0) + 1);
        }
    }

    let leastCount = Infinity;
    let leastFreqChar;

    // This will find the character(s) with the least count
    for(let [char, count] of charsCountMap.entries()){
        if(count < leastCount){
            leastCount = count;
            leastFreqChar = char;
        }
    }
    return leastFreqChar;
}

