```java
import java.util.*;
import java.lang.*;
import java.math.BigInteger;

public class Solution {

    public static int modp(int g, int n, int p) {
        BigInteger bg = BigInteger.valueOf(g);
        BigInteger bn = BigInteger.valueOf(n);
        BigInteger bp = BigInteger.valueOf(p);

        BigInteger res = bg.modPow(bn, bp);
        return res.intValue();
    }

    public static void main(String[] args) {
        System.out.println(modp(5,4, 497)); //prints 445
        System.out.println(modp(7,3, 517)); //prints 363
        System.out.println(modp(6,1, 311)); //prints 6
        System.out.println(modp(2, 10, 101)); //prints 36
        System.out.println(modp(10, 100, 701)); //prints 69
    }
}
```

This program uses the `modPow` method from `java.math.BigInteger`. `modPow` returns a BigInteger whose value is `(this ^ exponent) mod m`.

