import heapq



def dijkstra(s,g):

    color=[0]*n

    dis={}

    for i in range(n):

        dis[i]=float('inf')

    dis[s]=0

    heapq.heappush(pq,[0,s])

    while len(pq)!=0:

        t,u=heapq.heappop(pq)

        color[u]=2

        if dis[u]<t:

            continue

        for v,cost in g[u]:

            if color[v]!=2:

                if dis[u]+cost<dis[v]:

                    dis[v]=dis[u]+cost

                    color[v]=1

                    heapq.heappush(pq,[dis[v],v])

    return dis



