function smallestIntegerAmongThreeArrays(arr1, arr2, arr3) {
    const minArray = [arr1, arr2, arr3].map(arr =>
        arr.reduce((minValue, curValue) => {
            if (!Number.isInteger(curValue)) {
                return minValue;
            }
            return Math.min(minValue, curValue);
        }, Infinity)
    );
    return Math.min(...minArray);
