def count_chars(text):
    # Initialize an empty dictionary
    result = {}

    # Iterate over every character in the text
    for char in text:
        # Ignore spaces
        if char.isalpha():
            # If the character is already in the dictionary, increment its value
            if char in result:
                result[char] += 1
            # Else, add the character to the dictionary with a value of 1
            else:
