#include <iostream>
#include<vector>

int binary_search(std::vector<int>& list, int left, int right, int search) {
    if (right >= left) {
        int mid = left + (right - left) / 2;

        // If the element is at middle
        if (list[mid] == search)
            return mid;

        // If element is smaller than middle, it can only be in left subarray
        if (list[mid] > search)
            return binary_search(list, left, mid - 1, search);

        // Else the element is in right subarray
        return binary_search(list, mid + 1, right, search);
   }

   // We reach here when the element is not present in array
   return -1;
} 

