```python
import calendar

def is_valid_month(month: int) -> bool:
    return 1 <= month <= 12

def is_valid_year(year: int) -> bool:
    return 1 <= year <= 9999

def is_leap_year(year: int) -> bool:
    return (year % 4 == 0 and year % 100 != 0) or year % 400 == 0

def main():
    year, month = 0, 0
    while not is_valid_year(year):
        year = int(input("Enter a valid year (1-9999): "))

    while not is_valid_month(month):
        month = int(input("Enter a valid month (1-12): "))

    print("\nCalendar for the month {0}, {1}".format(calendar.month_name[month], year))
    print(calendar.month(year, month))

if __name__ == "__main__":
    main()
