  let properties = ['Header', 'Body', 'Footer'];

  // Validate PATCH payload
  for (let prop in req.body){
    if (!properties.includes(prop) || typeof req.body[prop] !== 'string') {
      return res.status(400).send('Invalid PATCH payload');
    }
  }

  // Clean the payload from XSS attacks and apply PATCH changes
  for (let prop in req.body){
    webpage[prop] = xss(req.body[prop]);
  }

  res.json(webpage);
});

