def generate_lucas_sequence(n):
    if n < 1:
        return []
    elif n == 1:
        return [2]
    elif n == 2:
        return [2, 1]
    else:
        sequence = [2, 1]
        while sequence[-1] + sequence[-2] <= n:
            sequence.append(sequence[-1] + sequence[-2])
        return sequence
