        findPrimes(2, 100);
    }

    static void findPrimes(int start, int end) {
        if(start > end) {
            return;
        }
        if(isPrime(start)) {
            System.out.println(start);
        }
        findPrimes(start + 1, end);
    }

    static boolean isPrime(int num) {
        if(num <= 1) {
            return false;
        }
        if(num == 2 || num == 3) {
            return true;
        }
        if(num % 2 == 0 || num % 3 == 0) {
            return false;
        }
        for(int i = 5; i * i <= num; i += 6) {
            if(num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}
