在上述例子中，我們嘗試找出 4 在二維陣列中的位置，當找到時就輸出它的位置。

一般來說，雙重 for-loop 的時間複雜度為 O(n^2)，這是因為每一個元素都需要被一一檢查。在我們的案例中，n 是二維陣列的行數或列數。

值得注意的是，如果二維陣列的尺寸（長度和寬度）是常數或者與問題的輸入尺度無關，那麼我們依然會認為這個操作的時間複雜度為 O(1)，因為它不會隨著輸入尺度的增長而增長。此外，如果我們可以提前知道元素的位置，或者這個二維陣列的結構具有可搜尋性質（例如，已排序或者具有特定的數據結構），那麼我們還有機會可以提前優化這個操作的時間複雜度。

static int kvm_ioctl_create_device(struct kvm *kvm,
				   struct kvm_create_device *cd)
{
	struct kvm_device_ops *ops = NULL;
	struct kvm_device *dev;
	bool test = cd->flags & KVM_CREATE_DEVICE_TEST;
	int ret;

	if (cd->type >= ARRAY_SIZE(kvm_device_ops_table))
		return -ENODEV;

	ops = kvm_device_ops_table[cd->type];
	if (ops == NULL)
		return -ENODEV;

	if (test)
		return 0;

	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		return -ENOMEM;

	dev->ops = ops;
	dev->kvm = kvm;

	mutex_lock(&kvm->lock);
	ret = ops->create(dev, cd->type);
	if (ret < 0) {
		mutex_unlock(&kvm->lock);
		kfree(dev);
		return ret;
	}
	list_add(&dev->vm_node, &kvm->devices);
	mutex_unlock(&kvm->lock);

	if (ops->init)
		ops->init(dev);

	ret = anon_inode_getfd(ops->name, &kvm_device_fops, dev, O_RDWR | O_CLOEXEC);
	if (ret < 0) {
		mutex_lock(&kvm->lock);
		list_del(&dev->vm_node);
		mutex_unlock(&kvm->lock);
		ops->destroy(dev);
		return ret;
	}

	kvm_get_kvm(kvm);
	cd->fd = ret;
	return 0;
}

