Sure, let's start by providing the erroneous C++ program that contains bugs.

```c++
#include <iostream>
#include <algorithm>
using namespace std;

int quickSelect(int arr[], int left, int right, int k) {
    if (left == right)
        return arr[left];

    int pivotIndex = right; 
    pivotIndex = partition(arr, left, right, pivotIndex);

    if (k == pivotIndex)
        return arr[k];
    else if (k < pivotIndex)
        return quickSelect(arr, left, pivotIndex - 1, k);
    else
        return quickSelect(arr, pivotIndex + 1, right, k);
}

int partition(int arr[], int left, int right, int pivotIndex) {
    int pivotValue = arr[pivotIndex];
    swap(arr[pivotIndex], arr[right]);
    int storeIndex = left;

    for (int i = left; i < right; i++)
        if (arr[i] < pivotValue) {
            swap(arr[i], arr[storeIndex]);
            storeIndex++;
        }

    swap(arr[right], arr[storeIndex]);
    return storeIndex;
}

int main() {
    int arr[] = {7, 2, 1, 6, 8, 5, 3, 4};
    int n = sizeof(arr) / sizeof(arr[0]);
    int k = 2;
    cout << "K'th smallest element is: " << quickSelect(arr, 0, n - 1, k) << endl;
    return 0;
}
```
The primary issue with this program is found in the quickSelect function. When we are using array with 0 based index then kth smallest will be at (k-1)th position not at kth position. So we should change all k to k - 1 in quickSelect function.

Here is the corrected C++ program:

```c++
#include <iostream>
#include <algorithm>
using namespace std;

int quickSelect(int arr[], int left, int right, int k) {
    if (left == right)
        return arr[left];

    int pivotIndex = right; 
    pivotIndex = partition(arr, left, right, pivotIndex);

    if (k - 1 == pivotIndex)
        return arr[k - 1];
    else if (k - 1 < pivotIndex)
        return quickSelect(arr, left, pivotIndex - 1, k);
    else
        return quickSelect(arr, pivotIndex + 1, right, k);
}

int partition(int arr[], int left, int right, int pivotIndex) {
    int pivotValue = arr[pivotIndex];
    swap(arr[pivotIndex], arr[right]);
    int storeIndex = left;

    for (int i = left; i < right; i++)
        if (arr[i] < pivotValue) {
            swap(arr[i], arr[storeIndex]);
            storeIndex++;
        }

    swap(arr[right], arr[storeIndex]);
    return storeIndex;
}

int main() {
    int arr[] = {7, 2, 1, 6, 8, 5, 3, 4};
    int n = sizeof(arr) / sizeof(arr[0]);
    int k = 2;
    cout << "K'th smallest element is: " << quickSelect(arr, 0, n - 1, k) << endl;
    return 0;
}
