def insert(root, z):

    y = None

    x = root

    while isinstance(x, Node):

        y = x

        if z.id < x.id:

            x = x.left

        else:

            x = x.right

    z.parent = y



    if y == None:

        root = z

    elif z.id < y.id:

        y.left = z

    else:

        y.right = z

    return root



