import random

class ShuffleIterator:
    def __init__(self, items):
        self.items = items
        random.shuffle(self.items)  # Shuffles the items
        self.index = 0

    def has_next(self):
        # Checks if there are still more elements
        return self.index < len(self.items)

    def next(self):
        if self.has_next():
            item = self.items[self.index]
            self.index += 1
            return item
        else:
            raise StopIteration("No more elements in the iterator")

# Usage
myArray = ["Hello", "World", "AI", "Machine Learning"]
myIter = ShuffleIterator(myArray)

while myIter.has_next():
    print(myIter.next())
