Here's a Node.js-based REST API server that supports CRUD operations on a customer's profile.

We'll use Express.js, a minimal web application framework, and MongoDB, a NoSQL database, and Mongoose, a MongoDB object modeling tool.

```javascript
const express = require('express');
const mongoose = require('mongoose');
const bodyParser = require('body-parser');

mongoose.connect('mongodb://localhost:27017/customersdb', { useNewUrlParser: true, useUnifiedTopology: true });

const CustomerSchema = mongoose.Schema({
    name: String,
    email: String,
    address: String
});

const Customer = mongoose.model('Customer', CustomerSchema);

const app = express();

app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));

// CREATE
app.post('/customer', (req, res) => {
    const customer = new Customer({
        name: req.body.name,
        email: req.body.email,
        address: req.body.address
    });
    customer.save()
        .then(data => res.send(data))
        .catch(err => res.status(500).send(err.message));
});

// READ
app.get('/customer/:id', (req, res) => {
    Customer.findById(req.params.id)
        .then(data => {
            if(!data) res.status(404).send("No customer found");
            else res.send(data);
        })
        .catch(err => res.send(err.message));
});

// UPDATE
app.put('/customer/:id', (req, res) => {
    Customer.findByIdAndUpdate(req.params.id, {
        name: req.body.name,
        email: req.body.email,
        address: req.body.address
    }, {new: true})
    .then(data => {
        if(!data) res.status(404).send("No customer found");
        else res.send(data);
    })
    .catch(err => res.send(err.message));
});

// DELETE
app.delete('/customer/:id', (req, res) => {
    Customer.findByIdAndRemove(req.params.id)
        .then(data => {
            if(!data) res.status(404).send("No customer found");
            else res.send({message: "Customer was deleted"});
        })
        .catch(err => res.send(err.message));
});

app.listen(3000, () => console.log('Server is running on port 3000.'));
```

