            if i >> j & 1:

                cut += 1

                pc += 1

        for w in range(W):

            whites[cut][w] += S[-1][w] == '1'

        flag = True

        for line in whites:

            for cnt in line:

                if cnt > K:

                    flag = False

        if not flag:

