```java
import java.time.LocalDate;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

public class HashMapExample {

    public static class Transaction {
        private Double amount;
        private LocalDate date;
        private String type;

        // getters and setters
    }

    public static class CustomerTransactions {
        private ConcurrentHashMap<String, List<Transaction>> customerTransactions = new ConcurrentHashMap<>();

        public List<Transaction> fetchTransactions(String email) {
            return customerTransactions.get(email).stream()
                .sorted(Comparator.comparing(Transaction::getDate).reversed())
                .collect(Collectors.toList());
        }

        public void addTransaction(String email, Transaction transaction) {
            customerTransactions.compute(email, (key, transactions) -> {
                if (transactions == null) {
                    transactions = new ArrayList<>();
                }
                transactions.add(transaction);
                return transactions;
            });
        }

        public double getTotalTransactionValue(String email) {
            return customerTransactions.get(email).stream()
                .mapToDouble(Transaction::getAmount)
                .sum();
        }

        public String getMostFrequentTransactionType(String email) {
            return customerTransactions.get(email).stream()
                .collect(Collectors.groupingBy(Transaction::getType, Collectors.counting()))
                .entrySet().stream()
                .max(Map.Entry.comparingByValue())
                .map(Map.Entry::getKey)
                .orElse(null);
        }
    }
}
```

