def can_empty(A,y,x):

    A[y][x],A[y][x+1] = A[y][x+1],A[y][x]

    num = sum(W-a.count(".") for a in A)

    while 1:

        # Fall processing

        for w in range(W):

            seq = ("".join(A[h][w] for h in range(H))).replace(".","")

            seq += "."*(H-len(seq))

            for h in range(H):

                A[h][w] = seq[h]



        # Banish processing

        B = [[0]*W for _ in range(H)]

        for h in range(H):

            cnt = 1

            for w in range(1,W):

                if A[h][w] == A[h][w-1]: cnt += 1

                else:

                    if cnt >= n and A[h][w-1] != ".":

                        for wi in range(w-cnt,w): B[h][wi] = 1

                    cnt = 1

            if cnt >= n and A[h][W-1] != ".":

                for wi in range(W-cnt,W): B[h][wi] = 1

        for w in range(W):

            cnt = 1

            for h in range(1,H):

                if A[h][w] == A[h-1][w]: cnt += 1

                else:

                    if cnt >= n and A[h-1][w] != ".":

                        for hi in range(h-cnt,h): B[hi][w] = 1

                    cnt = 1

            if cnt >= n and A[H-1][w] != ".":

                for hi in range(H-cnt,H): B[hi][w] = 1



        banish = False

        for h in range(H):

            for w in range(W):

                if B[h][w]:

                    A[h][w] = "."

                    num -= 1

                    banish = True

        if not banish: return False

        if num == 0: return True





