#include <iostream>
#include <thread>
#include <stdexcept>
#include <atomic>
#include <condition_variable>

std::condition_variable cv;
std::mutex cv_m;
std::atomic<bool> ready(false);

void calculateHarmonic(int n, double *result) {
    if (n <= 0) {
        throw std::invalid_argument("Entered value must be greater than zero");
    }
    *result = 0.0;
    for (int i = 1; i <= n; i++) {
        *result += 1.0 / (double) i;
    }
    std::this_thread::sleep_for(std::chrono::milliseconds(500)); // Simulates delays from server response
    ready = true;
    cv.notify_one();
}

int main() {
    int n;
    std::cout << "Enter a number: ";
    std::cin >> n;

    double result;
    std::thread t(calculateHarmonic, n, &result);

    while (!ready) {
        std::unique_lock<std::mutex> lk(cv_m);
        cv.wait(lk);
        if (!ready) {
            throw std::runtime_error("Server Disconnected");
        }
    }

    t.join();
    std::cout << "The result is: " << result << std::endl;

    return 0;
}
