def find_dissimilar(t1, t2):
    d1, d2 = {}, {}
    for el in t1:
        if el not in t2:
            d1[el] = (d1.get(el, (0,0))[0] + 1, 1)
    for el in t2:
        if el not in t1:
            d2[el] = (d2.get(el, (0,0))[0] + 1, 2)
    result = {**d1, **d2}
    common = set(t1) & set(t2)
    for el in common:
        result[el] = (t1.count(el), t2.count(el))
    return result
