```python
def temperature_conversion(initial_scale, final_scale, temp_value):
    error_message = 'Invalid temperature scale. Available scales are: Fahrenheit, Celsius, Kelvin, Rankine'
    initial_scale = initial_scale.lower()
    final_scale = final_scale.lower()

    if initial_scale not in ['fahrenheit', 'celsius', 'kelvin', 'rankine']:
        raise ValueError(error_message)

    if final_scale not in ['fahrenheit', 'celsius', 'kelvin', 'rankine']:
        raise ValueError(error_message)

    if initial_scale == 'celsius':
        if temp_value < -273.15:
            raise ValueError('Temperature below absolute zero is not possible')
    elif initial_scale == 'kelvin':
        if temp_value < 0:
            raise ValueError('Temperature below absolute zero is not possible')
        else:
            temp_value -= 273.15
    elif initial_scale == 'fahrenheit':
        if temp_value < -459.67:
            raise ValueError('Temperature below absolute zero is not possible')
        else:
            temp_value = (temp_value - 32) / 1.8
    elif initial_scale == 'rankine':
        if temp_value < 0:
            raise ValueError('Temperature below absolute zero is not possible')
        else:
            temp_value = (temp_value - 491.67) / 1.8

    if final_scale == 'celsius':
        converted_value = temp_value
    elif final_scale == 'kelvin':
        converted_value = temp_value + 273.15
    elif final_scale == 'fahrenheit':
        converted_value = (temp_value * 1.8) + 32
    else:  # Rankine
        converted_value = (temp_value + 273.15) * 1.8

    return round(converted_value, 2)

# Test the function
try:
    print(temperature_conversion('Fahrenheit', 'Celsius', -40)) # -40
    print(temperature_conversion('Fahrenheit', 'Kelvin', -40)) # 233.15
    print(temperature_conversion('Fahrenheit', 'Rankine', -40)) # 419.67
    print(temperature_conversion('Celsius', 'Kelvin', -40)) # 233.15
    print(temperature_conversion('Kelvin', 'Celsius', 0)) # -273.15
    print(temperature_conversion('Rankine', 'Celsius', 0)) # -273.15
except Exception as e:
    print(str(e))
```

This function first validates the inputs, then converts the initial temperature to Celsius. It also handles temperatures below the respective absolute zero for each scale. Then the function converts the temperature to the desired output scale. Finally, it returns the converted temperature, rounded to 2 decimal places for accuracy.

