```javascript
// 函數實現
function checkDivisibility(arr) {
  let divisibilityRuleFlag = false; 
  let divisibilityByTenFlag = false; 

  for(let i=0; i<arr.length; i++) {
    if(arr[i] % 2 === 0 || arr[i] % 5 === 0) {
      divisibilityRuleFlag = true; 
    }
    if(arr[i] % 10 === 0) {
      divisibilityByTenFlag = true;     
    }
  }

  if(divisibilityRuleFlag && divisibilityByTenFlag)
    return true
  return false
}

