import java.util.*;

public class Sportsman {
    private String name;
    private String sport;
    private String country;
    private int age;
    private int medals;
    private Set<WorldRecord> records;

    public Sportsman(String name, String sport, String country, int age) {
        this.name = name;
        this.sport = sport;
        this.country = country;
        this.age = age;
        this.medals = 0;
        this.records = new HashSet<WorldRecord>();
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getSport() {
        return sport;
    }

    public void setSport(String sport) {
        this.sport = sport;
    }

    public String getCountry() {
        return country;
    }

    public void setCountry(String country) {
        this.country = country;
    }

    public int getAge() {
        return age;
    }

    public void setAge(int age) {
        this.age = age;
    }

    public int getMedals() {
        return medals;
    }

    public void addMedal() {
        this.medals ++;
    }

    public boolean addRecord(WorldRecord record) {
        if(record.getSport().equals(this.sport)) {
            return records.add(record);
        }
        return false;
    }

    public static Sportsman maxMedals(Sportsman[] sportsmen) {
        int max = 0;
        Sportsman champion = null;
        for (Sportsman sportsman : sportsmen) {
            if (sportsman.getMedals() > max) {
                max = sportsman.getMedals();
                champion = sportsman;
            }
        }
        return champion;
    }
}

public class WorldRecord {
    private String name;
    private String sport;
    private String details;

    public WorldRecord(String name, String sport, String details) {
        this.name = name;
        this.sport = sport;
        this.details = details;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getSport() {
        return sport;
    }

    public void setSport(String sport) {
        this.sport = sport;
    }

    public String getDetails() {
        return details;
    }

    public void setDetails(String details) {
        this.details = details;
    }

    // Implementation of the equals and hashCode methods are required so that duplicate records can be prevented
    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if(o == null || getClass() != o.getClass()) return false;
        WorldRecord that = (WorldRecord) o;
        return Objects.equals(name, that.name) && Objects.equals(sport, that.sport) && Objects.equals(details, that.details);
    }

    @Override
    public int hashCode() {
        return Objects.hash(name, sport, details);
    }
}
