Here is a JavaScript function that generates the first 50 prime numbers:

```JavaScript
function findPrimes() {
  var primes = [];
  for(var i = 2; primes.length < 50; i++) {
    if(isPrime(i)) {
      primes.push(i);
    }
  }
  return primes;
}

function isPrime(num) {
  for(var i = 2, sqrt = Math.sqrt(num); i <= sqrt; i++) {
    if(num % i === 0) {
      return false;
    }
  }
  return num > 1;
}

console.log(findPrimes());
```

