import Foundation

func findMaxValue(in array: [Int]) -> Int? {
    // Check if array is not empty
    guard !array.isEmpty else {
        return nil
    }

    var max = array[0]
    for value in array {
        if value > max {
            max = value
        }
    }

    return max
}

